// Real last-change dates for sitemap <lastmod>, from lib/lastmod.gen.json
// (generated by scripts/gen-lastmod.mjs from git history at build time).
import dates from "./lastmod.gen.json";

// Static routes first, then fewer dynamic segments, so /jobs/fresher beats /jobs/[slug].
const PATTERNS = Object.entries(dates)
  .map(([route, iso]) => {
    const segs = route ? route.split("/") : [];
    const dynamic = segs.filter((s) => s.startsWith("[")).length;
    const re = new RegExp(
      "^" +
        segs
          .map((s) => (s.startsWith("[[...") || s.startsWith("[...") ? ".+" : s.startsWith("[") ? "[^/]+" : s.replace(/[.*+?^${}()|\\]/g, "\\$&")))
          .join("/") +
        "$"
    );
    return { re, dynamic, len: segs.length, iso };
  })
  .sort((a, b) => a.dynamic - b.dynamic || b.len - a.len);

/** Date of the last real change to the page that serves `url`, or undefined. */
export function lastModifiedFor(url) {
  let p;
  try {
    p = new URL(url).pathname;
  } catch {
    return undefined;
  }
  p = p.replace(/^\/+|\/+$/g, "");
  const hit = PATTERNS.find((x) => x.re.test(p));
  return hit ? new Date(hit.iso) : undefined;
}

/** Adds lastModified to sitemap entries that don't already carry a more specific date. */
export function withLastModified(entries) {
  return entries.map((e) => {
    if (e.lastModified) return e;
    const d = lastModifiedFor(e.url);
    return d ? { ...e, lastModified: d } : e;
  });
}
